namespace SimpleRouter.SourceGenerators;

internal static class AttributeSource
{
    public const string RouteAttributeName = "SimpleRouter.RouteAttribute";
    public const string GeneratedRouteFactoryAttributeName = "SimpleRouter.GeneratedRouteFactoryAttribute";
    public const string RouteViewAttributeName = "SimpleRouter.RouteViewAttribute";
    public const string GeneratedViewLocatorAttributeName = "SimpleRouter.GeneratedViewLocatorAttribute";

    public const string RouteAttribute = """
        // <auto-generated/>
        #nullable enable

        namespace SimpleRouter
        {
            /// <summary>
            /// Marks a class as a route for source-generated factory registration.
            /// The class must implement <see cref="IRoute"/>.
            /// </summary>
            [global::System.AttributeUsage(global::System.AttributeTargets.Class, Inherited = false, AllowMultiple = false)]
            [global::System.Diagnostics.Conditional("SIMPLEROUTER_GENERATOR")]
            internal sealed class RouteAttribute : global::System.Attribute
            {
                public string Group { get; set; } = "";
            }
        }
        """;

    public const string GeneratedRouteFactoryAttribute = """
        // <auto-generated/>
        #nullable enable

        namespace SimpleRouter
        {
            /// <summary>
            /// Marks a partial class to receive a source-generated <c>GeneratedCreateRoutes</c> method
            /// and a <c>CreateGeneratedRouteFactory</c> helper that returns a <see cref="RouteFactory"/> delegate.
            /// </summary>
            [global::System.AttributeUsage(global::System.AttributeTargets.Class, Inherited = false, AllowMultiple = false)]
            [global::System.Diagnostics.Conditional("SIMPLEROUTER_GENERATOR")]
            internal sealed class GeneratedRouteFactoryAttribute : global::System.Attribute
            {
                public string Group { get; set; } = "";
            }
        }
        """;

    public const string RouteViewAttribute = """
        // <auto-generated/>
        #nullable enable

        namespace SimpleRouter
        {
            /// <summary>
            /// Maps a View class to its corresponding Route (ViewModel) type for source-generated view location.
            /// </summary>
            [global::System.AttributeUsage(global::System.AttributeTargets.Class, Inherited = false, AllowMultiple = false)]
            [global::System.Diagnostics.Conditional("SIMPLEROUTER_GENERATOR")]
            internal sealed class RouteViewAttribute : global::System.Attribute
            {
                public RouteViewAttribute(global::System.Type routeType)
                {
                    RouteType = routeType;
                }

                public global::System.Type RouteType { get; }

                public string Group { get; set; } = "";
            }
        }
        """;

    public const string GeneratedViewLocatorAttribute = """
        // <auto-generated/>
        #nullable enable

        namespace SimpleRouter
        {
            /// <summary>
            /// Marks a partial <see cref="SimpleRouter.Avalonia.ViewLocatorBase"/> subclass to receive
            /// a source-generated <c>ResolveControl</c> override using pattern matching.
            /// </summary>
            [global::System.AttributeUsage(global::System.AttributeTargets.Class, Inherited = false, AllowMultiple = false)]
            [global::System.Diagnostics.Conditional("SIMPLEROUTER_GENERATOR")]
            internal sealed class GeneratedViewLocatorAttribute : global::System.Attribute
            {
                public string Group { get; set; } = "";
            }
        }
        """;
}
